export const nyBrandViewBoxes: Record<string, string> = {
  aws: '0 0 256 153',
  vscode: '0 0 256 254',
}

nyBrandIcons.douyin = nyBrandIcons.tiktok

export const nyIcons: Record<string, string[]> = { ...nyBaseIcons, ...nyExtraIcons, ...nyBrandIcons }

export type NyIconName = keyof typeof nyIcons

export const nyIconFallback = 'info'

export function nyIconPaths(name: string): string[] {
  return nyIcons[name] ?? nyIcons[nyIconFallback]
}

export function isFilledIcon(name: string): boolean {
  return name in nyBrandIcons
}

export function nyIconViewBox(name: string): string {
  return nyBrandViewBoxes[name] ?? '0 0 24 24'
}
